schema_ddl:
CREATE TABLE pat_reg (
    pat_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pat_nm TEXT NOT NULL,
    codice_fiscale_dimissione VARCHAR(16) UNIQUE NOT NULL,
    dob DATE NOT NULL
);

CREATE TABLE doc_dim (
    doc_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_medico VARCHAR(20) UNIQUE NOT NULL,
    spec_desc TEXT NOT NULL
);

CREATE TABLE diag_dim (
    diag_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_icd VARCHAR(10) UNIQUE NOT NULL,
    diag_desc TEXT NOT NULL
);

CREATE TABLE ward_dim (
    ward_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_reparto VARCHAR(10) UNIQUE NOT NULL,
    ward_nm TEXT NOT NULL
);

CREATE TABLE adm_fact (
    adm_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pat_id INT NOT NULL REFERENCES pat_reg(pat_id),
    doc_id INT NOT NULL REFERENCES doc_dim(doc_id),
    diag_id INT NOT NULL REFERENCES diag_dim(diag_id),
    ward_id INT NOT NULL REFERENCES ward_dim(ward_id),
    adm_ts VARCHAR(50) NOT NULL,
    los_days INT CHECK (los_days >= 0),
    tot_amt NUMERIC(10,2) CHECK (tot_amt >= 0.00)
);
